poseSubModel:
function poseSubModel(model, s = {}) {
  if (!model) return;
  const g = model.groups, st = model.state, dt = Number.isFinite(s.dt) ? Math.max(0, Math.min(0.25, s.dt)) : 0;
  st.t += dt;
  switch (model.id) {
    case 'autobomb': {
      const v = Number.isFinite(s.speed) ? s.speed : 0;
      st.stride = (st.stride || 0) + dt * v * 9;
      const k = Math.min(1, v / 1.5), sw = Math.sin(st.stride) * 0.5 * k;
      if (g.legL) g.legL.rotation.x = sw;
      if (g.legR) g.legR.rotation.x = -sw;
      if (g.body) g.body.position.y = Math.abs(Math.cos(st.stride)) * 0.012 * k;
      break;
    }
    case 'torpedo':
      if (g.prop) g.prop.rotation.z += dt * (s.flying === false ? 4 : 40);
      break;
    case 'sprinkler':
      if (g.head && Number.isFinite(s.spin)) g.head.rotation.y = s.spin;
      break;
    case 'beakon':
      if (g.dish) g.dish.rotation.y += dt * (s.active === false ? 0 : 1.1);
      break;
    case 'splashWall': {
      const u = Number.isFinite(s.unfold) ? Math.min(1, Math.max(0, s.unfold)) : 1;
      const arms = smoothstep(u * 1.6 - 0.6), grow = smoothstep(u * 1.4);
      model.root.scale.setScalar(SPLASH_WALL_FOLDED_SCALE + (1 - SPLASH_WALL_FOLDED_SCALE) * grow);
      // Folded (S3 icon): arms drawn in and pointing up in a bundle about the
      // tank's length, lower rod telescoped up toward the tank.
      const reach = 0.38 + 0.62 * arms;
      if (g.armR) { g.armR.rotation.z = (1 - arms) * Math.PI * 0.48; g.armR.scale.x = reach; }
      if (g.armL) { g.armL.rotation.z = -(1 - arms) * Math.PI * 0.48; g.armL.scale.x = reach; }
      if (g.leg) g.leg.scale.y = 0.42 + 0.58 * grow;
      if (g.curtain) {
        g.curtain.visible = u >= 0.999;
        const glow = model.materials.get('inkSheet');
        if (glow) glow.opacity = 0.18 + 0.06 * Math.sin(st.t * 23);
      }
      // Tank ink level follows the wall's remaining HP (presentation only).
      // Full is ~85% of the tank so the plunger and marks stay visible (refs).
      if (g.fill) g.fill.scale.y = 0.85 * Math.max(0.05, Number.isFinite(s.fill) ? Math.min(1, s.fill) : 1);
      break;
    }
    case 'inkMine':
      if (g.holo) {
        g.holo.visible = s.armed !== false;
        g.holo.rotation.y += dt * 0.6;
      }
      break;
    case 'fizzy': {
      const b = Number.isFinite(s.bulge) ? Math.min(1, Math.max(0, s.bulge)) : 0;
      if (g.body) g.body.scale.set(1 + 0.16 * b, 1 + 0.05 * b, 1 + 0.16 * b);
      break;
    }
    case 'toxicMistCloud':
      if (g.body) { g.body.rotation.y += dt * 0.35; g.body.scale.y = 1 + 0.04 * Math.sin(st.t * 1.7); }
      break;
    case 'spCrabTank': {
      // Crab Tank walk: the three legs a side swing about their hips in
      // alternating pairs with the ground speed (presentation only).
      const v = Number.isFinite(s.speed) ? s.speed : 0;
      st.stride = (st.stride || 0) + dt * v * 6;
      const k = Math.min(1, v / 2);
      const legSines=st.crabLegSines||=([]);
      for (let i = 0; i < 3; i++) {
        const [l, r] = CRAB_LEGS[i];
        const angle=st.stride+i*2.1;
        if(!g[l]&&!g[r])continue;
        const row=legSines[i]||=( {} );
        // sin(angle + PI) is not bit-identical to -sin(angle). Retain both
        // original expressions, reusing them only while the pose phase is idle.
        if(!Object.is(row.angle,angle)||row.sin!==Math.sin){
          row.angle=angle;row.sin=Math.sin;row.leftReady=row.rightReady=false;
        }
        if(g[l]){if(!row.leftReady){row.left=Math.sin(angle);row.leftReady=true;}g[l].rotation.y=row.left*0.22*k;}
        if(g[r]){if(!row.rightReady){row.right=Math.sin(angle+Math.PI);row.rightReady=true;}g[r].rotation.y=row.right*0.22*k;}
      }
      break;
    }
    case 'pointSensor': {
      const m = model.materials.get('inkGlow');
      if (m) m.emissiveIntensity = 1 + 0.8 * (0.5 + 0.5 * Math.sin(st.t * 9));
      break;
    }
    default: break;
  }
}
